Write-Host "=== Checking for .git repositories ===" -ForegroundColor Cyan
$paths = @(
    "c:\Users\sarlo\OneDrive\Escritorio\Test",
    "c:\Users\sarlo\OneDrive\Escritorio\Test.worktrees\copilot-worktree-2026-03-23T22-51-41"
)

foreach ($path in $paths) {
    if (Test-Path $path) {
        $gitPath = Join-Path $path ".git"
        if (Test-Path $gitPath) {
            Write-Host "$path has .git: YES" -ForegroundColor Green
            $gitConfig = Join-Path $gitPath "config"
            if (Test-Path $gitConfig) {
                Write-Host "Git remote URL:" -ForegroundColor Yellow
                Get-Content $gitConfig | Select-String "url"
            }
        } else {
            Write-Host "$path has .git: NO" -ForegroundColor Yellow
        }

        # Check for worktree info
        $worktreeFile = Join-Path $gitPath "worktreeConfig"
        if (Test-Path $worktreeFile) {
            Write-Host "This is a git worktree: YES" -ForegroundColor Green
        }
    } else {
        Write-Host "$path exists: NO" -ForegroundColor Red
    }
    Write-Host ""
}

